// Simple Asteroid Dodger game
// Canvas element with id="game" must exist in the HTML.

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas with id "game" not found');
  const ctx = canvas.getContext('2d');
  // Set canvas size to match its displayed size
  const resize = () => {
    canvas.width = canvas.clientWidth;
    canvas.height = canvas.clientHeight;
  };
  resize();
  window.addEventListener('resize', resize);

  // Player configuration
  const player = {
    width: 30,
    height: 15,
    x: canvas.width / 2,
    y: canvas.height - 30,
    speed: 5,
    moveLeft: false,
    moveRight: false,
    draw() {
      ctx.fillStyle = '#0f0';
      ctx.fillRect(this.x - this.width / 2, this.y, this.width, this.height);
    },
    update() {
      if (this.moveLeft) this.x -= this.speed;
      if (this.moveRight) this.x += this.speed;
      // Keep within bounds
      const half = this.width / 2;
      this.x = Math.max(half, Math.min(canvas.width - half, this.x));
    }
  };

  // Input handling
  window.addEventListener('keydown', e => {
    if (e.key === 'ArrowLeft' || e.key === 'a') player.moveLeft = true;
    if (e.key === 'ArrowRight' || e.key === 'd') player.moveRight = true;
  });
  window.addEventListener('keyup', e => {
    if (e.key === 'ArrowLeft' || e.key === 'a') player.moveLeft = false;
    if (e.key === 'ArrowRight' || e.key === 'd') player.moveRight = false;
  });

  // Asteroid management
  const asteroids = [];
  const spawnInterval = 1000; // ms
  let lastSpawn = 0;

  const spawnAsteroid = () => {
    const radius = 15;
    const x = Math.random() * (canvas.width - 2 * radius) + radius;
    const speed = 2 + Math.random() * 2; // 2-4
    asteroids.push({ x, y: -radius, radius, speed });
  };

  const updateAsteroids = (delta) => {
    for (let a of asteroids) a.y += a.speed;
    // Remove off‑screen
    while (asteroids.length && asteroids[0].y - asteroids[0].radius > canvas.height) {
      asteroids.shift();
    }
  };

  const drawAsteroids = () => {
    ctx.fillStyle = '#a52a2a';
    for (let a of asteroids) {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.radius, 0, Math.PI * 2);
      ctx.fill();
    }
  };

  const checkCollision = () => {
    for (let a of asteroids) {
      const dx = a.x - player.x;
      const dy = a.y - (player.y + player.height / 2);
      const distance = Math.hypot(dx, dy);
      if (distance < a.radius + Math.max(player.width, player.height) / 2) {
        return true;
      }
    }
    return false;
  };

  let gameOver = false;
  let lastTime = 0;
  const loop = (timestamp) => {
    if (!lastTime) lastTime = timestamp;
    const delta = timestamp - lastTime;
    lastTime = timestamp;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Spawn asteroids
    if (timestamp - lastSpawn > spawnInterval) {
      spawnAsteroid();
      lastSpawn = timestamp;
    }

    player.update();
    player.draw();

    updateAsteroids(delta);
    drawAsteroids();

    if (checkCollision()) {
      gameOver = true;
    }

    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#fff';
      ctx.font = '24px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
    } else {
      requestAnimationFrame(loop);
    }
  };

  requestAnimationFrame(loop);
})();
